import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] mx, ad;

    static void update(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            mx[node]++;
            ad[node]++;
            return;
        }
        int mid = (l + r) / 2;
        if (ql <= mid) update(2 * node, l, mid, ql, qr);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr);
        mx[node] = Math.max(mx[2 * node], mx[2 * node + 1]) + ad[node];
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] bk = new long[(int) n][2];
        for (int i = 0; i < bk.length; i++) {
            for (int j = 0; j < bk[i].length; j++) {
                bk[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n;
        long[] all = new long[2 * cn];
        for (int i = 0; i < cn; i++) {
            all[2 * i] = bk[i][0];
            all[2 * i + 1] = bk[i][1];
        }
        Arrays.sort(all);
        int u = 0;
        for (int i = 0; i < all.length; i++) {
            if (i == 0 || all[i] != all[i - 1]) all[u++] = all[i];
        }
        int m = u - 1;
        mx = new int[4 * m + 4];
        ad = new int[4 * m + 4];
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < cn; i++) {
            int a = Arrays.binarySearch(all, 0, u, bk[i][0]);
            int b = Arrays.binarySearch(all, 0, u, bk[i][1]);
            update(1, 0, m - 1, a, b - 1);
            if (i > 0) out.append(" ");
            out.append(mx[1]);
        }
        System.out.println(out);
    }
}
